param([string]$BaseUrl='http://127.0.0.1:8788',[switch]$SelfTest)
$ErrorActionPreference='Stop'
$BaseUrl=$BaseUrl.TrimEnd('/')
if($BaseUrl-ne'http://127.0.0.1:8788'){throw 'Router VPN Windows product app only uses the fixed local controller.'}
Add-Type -AssemblyName PresentationFramework
Add-Type -AssemblyName PresentationCore
Add-Type -AssemblyName WindowsBase
[xml]$Xaml=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Router VPN" Height="800" Width="1180" MinHeight="680" MinWidth="980" WindowStartupLocation="CenterScreen" Background="#0B1020" Foreground="#F5F7FF">
<Grid Margin="18"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
<Grid Grid.Row="0" Margin="4,0,4,14"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel><TextBlock Text="Router VPN" FontSize="30" FontWeight="Bold"/><TextBlock Name="HeaderDetail" Text="Native Windows product app" Foreground="#93A4C7"/></StackPanel><Border Grid.Column="1" Background="#152038" CornerRadius="16" Padding="16,8"><StackPanel Orientation="Horizontal"><Ellipse Name="StateDot" Width="10" Height="10" Fill="#6B7280" Margin="0,0,8,0"/><TextBlock Name="StateText" Text="Checking..." FontWeight="SemiBold"/></StackPanel></Border></Grid>
<TabControl Grid.Row="1" Background="#0F172A" BorderBrush="#263452" Foreground="#E8ECF8">
<TabItem Header="Home / Connect"><ScrollViewer><StackPanel Margin="12"><GroupBox Header="Connection" Margin="8" Padding="10"><StackPanel><TextBlock Text="Router"/><ComboBox Name="RouterCombo" DisplayMemberPath="name" SelectedValuePath="id" Margin="4"/><TextBlock Text="Mode" Margin="0,8,0,0"/><ComboBox Name="ModeCombo" DisplayMemberPath="name" SelectedValuePath="id" Margin="4"/><TextBlock Text="Tunnel base" Margin="0,8,0,0"/><ComboBox Name="BaseCombo" Margin="4"><ComboBoxItem Content="Auto" Tag="auto"/><ComboBoxItem Content="WireGuard" Tag="wg"/><ComboBoxItem Content="AmneziaWG" Tag="awg"/></ComboBox><WrapPanel Margin="0,12,0,0"><Button Name="AutoButton" Content="AUTO Connect" Margin="4" Padding="13,8"/><Button Name="ConnectButton" Content="Connect Selected" Margin="4" Padding="13,8"/><Button Name="DisconnectButton" Content="Disconnect" Margin="4" Padding="13,8"/><Button Name="RefreshButton" Content="Refresh" Margin="4" Padding="13,8"/></WrapPanel><TextBlock Name="ConnectionDetail" TextWrapping="Wrap" Margin="4,12,4,0" Foreground="#A8B6D5"/></StackPanel></GroupBox><GroupBox Header="Connection proof" Margin="8" Padding="10"><StackPanel><TextBlock Name="ProofText" Text="Connected requires exact selected-router private path proof." TextWrapping="Wrap"/><TextBlock Name="LastErrorText" Foreground="#FF9CA8" TextWrapping="Wrap"/></StackPanel></GroupBox></StackPanel></ScrollViewer></TabItem>
<TabItem Header="Nodes / Map"><Grid Margin="14"><Grid.RowDefinitions><RowDefinition Height="240"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><Border Background="#0E182B" BorderBrush="#33415F" BorderThickness="1" CornerRadius="10"><Canvas Name="MapCanvas" ClipToBounds="True"/></Border><WrapPanel Grid.Row="1" Margin="0,8,0,0"><TextBlock Text="Order:" VerticalAlignment="Center" Margin="4"/><Button Name="SortCurrentButton" Content="Current / recent" Margin="4"/><Button Name="SortRecentButton" Content="Last used" Margin="4"/><Button Name="SortLatencyButton" Content="Lowest latency" Margin="4"/><Button Name="SortNameButton" Content="Name" Margin="4"/><Button Name="SelectLowestLatencyButton" Content="Select lowest measured" Margin="4"/></WrapPanel><DataGrid Grid.Row="2" Name="NodesGrid" AutoGenerateColumns="False" IsReadOnly="True" Margin="0,10,0,0"><DataGrid.Columns><DataGridTextColumn Header="Name" Binding="{Binding name}" Width="2*"/><DataGridTextColumn Header="Location" Binding="{Binding location}" Width="*"/><DataGridTextColumn Header="Endpoint" Binding="{Binding endpoint}" Width="2*"/><DataGridTextColumn Header="Median ms" Binding="{Binding latency_median_ms}" Width="*"/><DataGridTextColumn Header="Last used" Binding="{Binding last_used_at}" Width="2*"/></DataGrid.Columns></DataGrid><WrapPanel Grid.Row="3"><Button Name="PairNodeButton" Content="Pair home node" Margin="4"/><Button Name="ImportNodeButton" Content="Import node JSON" Margin="4"/><Button Name="ExternalDirectButton" Content="Connect external direct" Margin="4"/><Button Name="ExternalViaEntryButton" Content="External via Advanced entry" Margin="4"/><Button Name="SelectNodeButton" Content="Select highlighted node" Margin="4"/><Button Name="DeleteNodeButton" Content="Remove highlighted node" Margin="4"/><Button Name="LatencyButton" Content="Run 50-sample latency" Margin="4"/></WrapPanel></Grid></TabItem>
<TabItem Header="Modes"><Grid Margin="14"><DataGrid Name="ModesGrid" AutoGenerateColumns="False" IsReadOnly="True"><DataGrid.Columns><DataGridTextColumn Header="Mode" Binding="{Binding name}" Width="2*"/><DataGridCheckBoxColumn Header="Available" Binding="{Binding available}" Width="90"/><DataGridTextColumn Header="Ready bases" Binding="{Binding ready_bases_text}" Width="130"/><DataGridTextColumn Header="Reason" Binding="{Binding reason}" Width="3*"/></DataGrid.Columns></DataGrid></Grid></TabItem>
<TabItem Header="DNS"><StackPanel Margin="18"><TextBlock Text="DNS" FontSize="20" FontWeight="Bold"/><TextBlock Name="DnsSummary" TextWrapping="Wrap" Margin="0,8,0,12"/><Button Name="DnsButton" Content="Retest home-exit DNS" HorizontalAlignment="Left"/><TextBlock Text="Saved DNS is not proof; session proof reports active runtime enforcement and resolver success." TextWrapping="Wrap" Margin="0,12,0,0"/></StackPanel></TabItem>
<TabItem Header="Advanced"><ScrollViewer><StackPanel Margin="18"><TextBlock Text="Advanced" FontSize="20" FontWeight="Bold"/><TextBlock Name="AdvancedSummary" TextWrapping="Wrap" Margin="0,8,0,12"/><GroupBox Header="Real multihop" Padding="10"><StackPanel><TextBlock Text="Traffic path: client TUN -> exit transport -> entry WireGuard -> exit node -> Internet. Entry and exit must be different nodes. The selected Entry can also be used as the upstream hop for an external exit from Nodes / Map." TextWrapping="Wrap"/><TextBlock Text="Entry node" Margin="0,10,0,0"/><ComboBox Name="MultihopEntryCombo" DisplayMemberPath="name" SelectedValuePath="id" Margin="4"/><TextBlock Text="Exit node" Margin="0,8,0,0"/><ComboBox Name="MultihopExitCombo" DisplayMemberPath="name" SelectedValuePath="id" Margin="4"/><TextBlock Text="Exit transport" Margin="0,8,0,0"/><ComboBox Name="MultihopExitModeCombo" Margin="4"><ComboBoxItem Content="Shadowsocks" Tag="shadowsocks"/><ComboBoxItem Content="Hysteria2" Tag="hysteria2"/></ComboBox><WrapPanel Margin="0,10,0,0"><Button Name="MultihopConnectButton" Content="Connect real multihop" Margin="4" Padding="13,8"/><Button Name="MultihopRefreshButton" Content="Refresh multihop" Margin="4" Padding="13,8"/></WrapPanel><TextBlock Name="MultihopSummary" TextWrapping="Wrap" Margin="4,10,4,0" Foreground="#A8B6D5"/></StackPanel></GroupBox></StackPanel></ScrollViewer></TabItem>
<TabItem Header="Forwarding"><StackPanel Margin="18"><TextBlock Text="Forwarding" FontSize="20" FontWeight="Bold"/><TextBlock Text="Incoming forwarding is managed by the authenticated private Setup Center/router-agent surface. This client never exposes an admin token or fakes DNAT in proxy-only modes." TextWrapping="Wrap" Margin="0,8,0,0"/></StackPanel></TabItem>
<TabItem Header="Settings"><StackPanel Margin="18"><TextBlock Text="Settings" FontSize="20" FontWeight="Bold"/><TextBlock Name="SettingsSummary" TextWrapping="Wrap" Margin="0,8,0,12"/><Button Name="SettingsRefreshButton" Content="Refresh local state" HorizontalAlignment="Left"/></StackPanel></TabItem>
<TabItem Header="Help"><StackPanel Margin="18"><TextBlock Text="Help" FontSize="20" FontWeight="Bold"/><TextBlock Text="Install once, securely pair/import Router VPN or validated external node data separately, choose node/mode, connect, then prove the selected node, public exit and DNS. External protocol credentials stay in the controller private store and never appear in this UI." TextWrapping="Wrap" Margin="0,8,0,12"/><Button Name="TutorialButton" Content="Run full native onboarding again" HorizontalAlignment="Left"/></StackPanel></TabItem>
<TabItem Header="Diagnostics"><StackPanel Margin="18"><TextBlock Text="Typed connection progress and proof" FontSize="20" FontWeight="Bold"/><WrapPanel><Button Name="PublicIpButton" Content="Prove public VPN exit" Margin="4"/><Button Name="EmergencyButton" Content="Emergency stop" Margin="4"/></WrapPanel><TextBox Name="DiagnosticsBox" Height="380" IsReadOnly="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto"/></StackPanel></TabItem>
</TabControl><TextBlock Grid.Row="2" Margin="4,12,4,0" Foreground="#7E90B6" Text="Native WPF; fixed local controller 127.0.0.1:8788; no browser or embedded web surface."/></Grid></Window>
'@
$Reader=New-Object System.Xml.XmlNodeReader $Xaml
$Window=[Windows.Markup.XamlReader]::Load($Reader)
function Control([string]$Name){return $Window.FindName($Name)}
if($SelfTest){
 foreach($Name in @('StateText','RouterCombo','ModeCombo','MapCanvas','NodesGrid','ModesGrid','DnsSummary','AdvancedSummary','MultihopEntryCombo','MultihopExitCombo','MultihopExitModeCombo','MultihopConnectButton','MultihopSummary','DiagnosticsBox','TutorialButton','PairNodeButton','ImportNodeButton','ExternalDirectButton','ExternalViaEntryButton','DeleteNodeButton','SortCurrentButton','SortRecentButton','SortLatencyButton','SortNameButton','SelectLowestLatencyButton')){if(-not(Control $Name)){throw "Windows product self-test missing $Name"}}
 $Source=Get-Content -LiteralPath $MyInvocation.MyCommand.Path -Raw
 foreach($Marker in @('/api/status','/api/profiles','/api/nodes?sort=','/api/logical-modes','/api/connect-logical','/api/session','/api/session/events','/api/multihop/status','/api/multihop/connect','/api/emergency-stop','/api/profile/pair','/api/profile/import','/api/external-profile/import','/api/external-profile/connect','entry_id','/api/profile/delete','latitude','longitude','No real node coordinates','Select lowest measured','last_used_at','Forwarding','Settings','Help')){if($Source-notlike"*$Marker*"){throw "Windows product contract missing $Marker"}}
 Write-Host 'Router VPN Windows product self-test: OK'
 exit 0
}
$StateText=Control 'StateText';$StateDot=Control 'StateDot';$HeaderDetail=Control 'HeaderDetail';$RouterCombo=Control 'RouterCombo';$ModeCombo=Control 'ModeCombo';$BaseCombo=Control 'BaseCombo';$ConnectionDetail=Control 'ConnectionDetail';$ProofText=Control 'ProofText';$LastErrorText=Control 'LastErrorText';$NodesGrid=Control 'NodesGrid';$MapCanvas=Control 'MapCanvas';$ModesGrid=Control 'ModesGrid';$DnsSummary=Control 'DnsSummary';$AdvancedSummary=Control 'AdvancedSummary';$SettingsSummary=Control 'SettingsSummary';$DiagnosticsBox=Control 'DiagnosticsBox';$MultihopEntryCombo=Control 'MultihopEntryCombo';$MultihopExitCombo=Control 'MultihopExitCombo';$MultihopExitModeCombo=Control 'MultihopExitModeCombo';$MultihopSummary=Control 'MultihopSummary'
$script:EventSeq=[uint64]0;$script:Busy=$false;$script:NodeSort='current'
function Api{param([string]$Path,[string]$Method='GET',$Body=$null,[int]$Timeout=45);$Uri="$BaseUrl$Path";if($Method-eq'GET'){return Invoke-RestMethod -Uri $Uri -Method Get -TimeoutSec $Timeout};$Json=if($null-eq$Body){'{}'}else{$Body|ConvertTo-Json -Depth 12 -Compress};return Invoke-RestMethod -Uri $Uri -Method $Method -ContentType 'application/json' -Body $Json -TimeoutSec $Timeout}
function ApiRaw{param([string]$Path,[byte[]]$Bytes,[int]$Timeout=45);return Invoke-RestMethod -Uri "$BaseUrl$Path" -Method Post -ContentType 'application/json' -Body $Bytes -TimeoutSec $Timeout}
function Log([string]$Text){$DiagnosticsBox.AppendText("[$(Get-Date -Format 'HH:mm:ss')] $Text`r`n");$DiagnosticsBox.ScrollToEnd()}
function BaseChoice{$Item=$BaseCombo.SelectedItem;if($Item-and$Item.Tag){return [string]$Item.Tag};return 'auto'}
function MultihopExitModeChoice{$Item=$MultihopExitModeCombo.SelectedItem;if($Item-and$Item.Tag){return [string]$Item.Tag};return 'shadowsocks'}
function SelectedNode{if(-not$NodesGrid.SelectedItem){throw 'Highlight a node first.'};return $NodesGrid.SelectedItem}
function AddLine($x1,$y1,$x2,$y2,[string]$Color){$Line=New-Object Windows.Shapes.Line;$Line.X1=$x1;$Line.Y1=$y1;$Line.X2=$x2;$Line.Y2=$y2;$Line.Stroke=$Color;$Line.StrokeThickness=1;[void]$MapCanvas.Children.Add($Line)}
function DrawMap($Profiles,[string]$Selected){$MapCanvas.Children.Clear();$Width=[Math]::Max(640,[double]$MapCanvas.ActualWidth);$Height=[Math]::Max(200,[double]$MapCanvas.ActualHeight);foreach($Lon in @(-120,-60,0,60,120)){$X=($Lon+180)/360*$Width;AddLine $X 0 $X $Height '#2D3D57'};foreach($Lat in @(-60,-30,0,30,60)){$Y=(90-$Lat)/180*$Height;AddLine 0 $Y $Width $Y '#2D3D57'};$Count=0;foreach($Profile in @($Profiles)){try{$Lat=[Convert]::ToDouble($Profile.latitude,[Globalization.CultureInfo]::InvariantCulture);$Lon=[Convert]::ToDouble($Profile.longitude,[Globalization.CultureInfo]::InvariantCulture)}catch{continue};if($Lat-lt-90-or$Lat-gt90-or$Lon-lt-180-or$Lon-gt180-or($Lat-eq0-and$Lon-eq0)){continue};$X=($Lon+180)/360*$Width;$Y=(90-$Lat)/180*$Height;$Dot=New-Object Windows.Shapes.Ellipse;$Dot.Width=if([string]$Profile.id-eq$Selected){16}else{12};$Dot.Height=$Dot.Width;$Dot.Fill=if([string]$Profile.id-eq$Selected){'#7B68FF'}else{'#62D5FF'};[Windows.Controls.Canvas]::SetLeft($Dot,$X-$Dot.Width/2);[Windows.Controls.Canvas]::SetTop($Dot,$Y-$Dot.Height/2);$Dot.ToolTip="$($Profile.name) latitude=$Lat longitude=$Lon";[void]$MapCanvas.Children.Add($Dot);$Count++};if($Count-eq0){$Empty=New-Object Windows.Controls.TextBlock;$Empty.Text='No real node coordinates in linked profiles';$Empty.Foreground='#AEBBD5';[Windows.Controls.Canvas]::SetLeft($Empty,20);[Windows.Controls.Canvas]::SetTop($Empty,20);[void]$MapCanvas.Children.Add($Empty)}}
function SessionEvents{try{$Timeline=Api ("/api/session/events?after="+$script:EventSeq) -Timeout 3;foreach($Event in @($Timeline.events)){$Seq=[uint64]$Event.seq;if($Seq-le$script:EventSeq){continue};$Parts=@([string]$Event.phase);if($Event.runtime_mode){$Parts+=("runtime="+$Event.runtime_mode)};if($Event.base){$Parts+=("base="+$Event.base)};if($Event.message){$Parts+=$Event.message};Log ("Session #$Seq $($Event.type): $($Parts-join' | ')");$script:EventSeq=$Seq};if([uint64]$Timeline.last_event_seq-gt$script:EventSeq){$script:EventSeq=[uint64]$Timeline.last_event_seq}}catch{}}
function RefreshMultihop{try{$MH=Api '/api/multihop/status' -Timeout 5;$Nodes=@($MH.nodes);$EntrySelected=[string]$MultihopEntryCombo.SelectedValue;$ExitSelected=[string]$MultihopExitCombo.SelectedValue;$MultihopEntryCombo.ItemsSource=$Nodes;$MultihopExitCombo.ItemsSource=$Nodes;if(-not$EntrySelected-and$MH.entry_id){$EntrySelected=[string]$MH.entry_id};if(-not$ExitSelected-and$MH.exit_id){$ExitSelected=[string]$MH.exit_id};if($EntrySelected){$MultihopEntryCombo.SelectedValue=$EntrySelected};if($ExitSelected){$MultihopExitCombo.SelectedValue=$ExitSelected};$MultihopSummary.Text="Supported=$($MH.platform_supported) Connected=$($MH.connected) Actual exit=$($MH.actual_exit_id) Runtime=$($MH.runtime_exit_mode) Entry bases=$(@($MH.supported_entry_bases)-join',') Exit modes=$(@($MH.supported_exit_modes)-join',')"}catch{$MultihopSummary.Text="Multihop status unavailable: $($_.Exception.Message)"}}
function RefreshProduct{if($script:Busy){return};$script:Busy=$true;try{$Status=Api '/api/status' -Timeout 3;$Connected=[bool]$Status.connected;$StateText.Text=if($Connected){'Connected'}elseif($Status.phase){$Status.phase}else{'Off'};$StateDot.Fill=if($Connected){'#35D07F'}elseif($Status.phase-eq'failed'){'#FF5D6C'}else{'#6B7280'};$Runtime=if($Status.runtime_mode){$Status.runtime_mode}else{$Status.mode};$ConnectionDetail.Text="Phase: $($Status.phase) Logical: $($Status.logical_mode) Runtime: $Runtime Base: $($Status.base) Router: $($Status.router_id)";$LastErrorText.Text=[string]$Status.last_error;if($Connected){$ProofText.Text='Connected - selected-router private path proof passed.'};$Store=Api ("/api/nodes?sort="+$script:NodeSort) -Timeout 3;$Profiles=@($Store.profiles);$OldNode=[string]$NodesGrid.SelectedValue;$RouterCombo.ItemsSource=$Profiles;$NodesGrid.ItemsSource=$Profiles;if($Store.selected_id){$RouterCombo.SelectedValue=[string]$Store.selected_id};if($OldNode){$NodesGrid.SelectedValue=$OldNode};DrawMap $Profiles ([string]$Store.selected_id);$Selected=@($Profiles|Where-Object{[string]$_.id-eq[string]$Store.selected_id}|Select-Object -First 1);if($Selected.Count){$Profile=$Selected[0];$AdvancedSummary.Text="LAN=$($Profile.home_lan_access) Kill switch=$($Profile.kill_switch_policy) MTU=$($Profile.mtu_mode) Effective MTU=$($Profile.effective_mtu) Multihop=$($Profile.multihop_enabled)";$SettingsSummary.Text="Node=$($Profile.name) Endpoint=$($Profile.endpoint) Location=$($Profile.location)"};$Session=Api '/api/session' -Timeout 3;$Dns=$Session.dns_proof;$DnsSummary.Text="Mode=$($Dns.mode) Resolver=$($Dns.host) Proof=$($Dns.status) Latency=$($Dns.latency_ms)ms Reason=$($Dns.reason)";$Modes=@(Api '/api/logical-modes' -Timeout 12);foreach($Mode in $Modes){$Mode|Add-Member -NotePropertyName ready_bases_text -NotePropertyValue ((@($Mode.ready_bases)-join', ').ToUpperInvariant()) -Force};$ModesGrid.ItemsSource=$Modes;$ModeCombo.ItemsSource=@($Modes|Where-Object{$_.available});if(-not$ModeCombo.SelectedValue-and$ModeCombo.Items.Count-gt0){$ModeCombo.SelectedIndex=0};$HeaderDetail.Text="Native Windows product - $($Profiles.Count) linked node(s) - order $($script:NodeSort)";RefreshMultihop;SessionEvents}catch{$StateText.Text='Controller unavailable';$StateDot.Fill='#FF5D6C';$LastErrorText.Text=$_.Exception.Message}finally{$script:Busy=$false}}
function ShowPairNodeDialog{
 [xml]$DialogXaml=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" Title="Pair Router VPN node" Height="270" Width="470" WindowStartupLocation="CenterOwner" ResizeMode="NoResize"><StackPanel Margin="18"><TextBlock Text="Create a 6-digit one-time code in the authenticated private Setup Center." TextWrapping="Wrap" Margin="0,0,0,12"/><TextBlock Text="AI Board LAN IP / hostname"/><TextBox Name="PairHost" Text="192.168.50.133" Margin="0,4,0,10"/><TextBlock Text="One-time pairing code"/><PasswordBox Name="PairCode" MaxLength="6" Margin="0,4,0,14"/><StackPanel Orientation="Horizontal" HorizontalAlignment="Right"><Button Name="Cancel" Content="Cancel" MinWidth="90" Margin="4"/><Button Name="OK" Content="Pair" MinWidth="90" Margin="4" IsDefault="True"/></StackPanel></StackPanel></Window>
'@
 $R=New-Object System.Xml.XmlNodeReader $DialogXaml;$D=[Windows.Markup.XamlReader]::Load($R);$D.Owner=$Window;$H=$D.FindName('PairHost');$C=$D.FindName('PairCode');$OK=$D.FindName('OK');$Cancel=$D.FindName('Cancel');$script:PairAccepted=$false;$OK.Add_Click({$script:PairAccepted=$true;$D.Close()});$Cancel.Add_Click({$D.Close()});[void]$D.ShowDialog();if(-not$script:PairAccepted){return};$HostValue=[string]$H.Text;$CodeValue=[string]$C.Password;if($CodeValue-notmatch'^\d{6}$'){throw 'Pairing code must be exactly 6 digits.'};$Result=Api '/api/profile/pair' 'POST' @{host=$HostValue;code=$CodeValue} 20;Log ("Paired node: $($Result.profile.name)");RefreshProduct
}
function ImportAnyNode([byte[]]$Bytes){
 try{return @{kind='router-vpn';result=(ApiRaw '/api/profile/import' $Bytes 25)}}catch{$RouterError=$_.Exception.Message}
 try{return @{kind='external';result=(ApiRaw '/api/external-profile/import' $Bytes 25)}}catch{throw "Rejected as Router VPN bundle ($RouterError) and external schema-v3 node ($($_.Exception.Message))"}
}
function ConnectExternal([bool]$ViaEntry){
 $Profile=SelectedNode
 $Body=@{profile_id=[string]$Profile.id}
 if($ViaEntry){$Entry=[string]$MultihopEntryCombo.SelectedValue;if(-not$Entry){throw 'Choose an entry node in Advanced first.'};if($Entry-eq[string]$Profile.id){throw 'External entry and exit must be different nodes.'};$Body.entry_id=$Entry}
 $Result=Api '/api/external-profile/connect' 'POST' $Body 180
 Log ("External connect passed exact exit proof: "+($Result|ConvertTo-Json -Depth 6 -Compress))
}
function SelectLowestMeasuredNode{
 $Store=Api '/api/nodes?sort=latency' -Timeout 5
 $Measured=@($Store.profiles|Where-Object { ([int]$_.latency_samples -gt 0) -and ([double]$_.latency_median_ms -gt 0) })
 if($Measured.Count-lt2){throw 'Run real 50-sample latency tests on at least two usable nodes first; current selection was kept.'}
 $Best=$Measured[0]
 [void](Api '/api/profile/select' 'POST' @{id=[string]$Best.id} 10)
 $script:NodeSort='latency'
 Log ("Selected lowest measured median-latency node $($Best.name): $($Best.latency_median_ms)ms")
}
(Control 'RefreshButton').Add_Click({RefreshProduct});(Control 'SettingsRefreshButton').Add_Click({RefreshProduct});(Control 'SortCurrentButton').Add_Click({$script:NodeSort='current';RefreshProduct});(Control 'SortRecentButton').Add_Click({$script:NodeSort='last-used';RefreshProduct});(Control 'SortLatencyButton').Add_Click({$script:NodeSort='latency';RefreshProduct});(Control 'SortNameButton').Add_Click({$script:NodeSort='name';RefreshProduct});(Control 'SelectLowestLatencyButton').Add_Click({try{SelectLowestMeasuredNode}catch{Log ("Lowest-latency selection: $($_.Exception.Message)")};RefreshProduct});(Control 'MultihopRefreshButton').Add_Click({RefreshMultihop});(Control 'MultihopConnectButton').Add_Click({try{$Entry=[string]$MultihopEntryCombo.SelectedValue;$Exit=[string]$MultihopExitCombo.SelectedValue;if(-not$Entry-or-not$Exit){throw 'Choose both an entry and exit node.'};if($Entry-eq$Exit){throw 'Multihop entry and exit nodes must be different.'};$Result=Api '/api/multihop/connect' 'POST' @{entry_id=$Entry;exit_id=$Exit;base='wg';exit_mode=(MultihopExitModeChoice)} 180;Log ("Multihop connected entry=$($Result.entry_id) exit=$($Result.exit_id) mode=$($Result.exit_mode)")}catch{Log ("Multihop failed: $($_.Exception.Message)")};RefreshProduct});(Control 'AutoButton').Add_Click({try{$Result=Api '/api/auto' 'POST' @{} 120;Log ("AUTO runtime=$($Result.runtime_mode)")}catch{Log ("AUTO failed: $($_.Exception.Message)")};RefreshProduct});(Control 'ConnectButton').Add_Click({try{$Mode=[string]$ModeCombo.SelectedValue;if(-not$Mode){throw 'Choose an available mode.'};$Result=Api '/api/connect-logical' 'POST' @{mode=$Mode;base=(BaseChoice)} 150;Log ("Connected runtime=$($Result.runtime_mode) base=$($Result.base)")}catch{Log ("Connect failed: $($_.Exception.Message)")};RefreshProduct});(Control 'DisconnectButton').Add_Click({try{[void](Api '/api/disconnect' 'POST' @{} 15);Log 'Disconnected'}catch{Log $_.Exception.Message};RefreshProduct});(Control 'PublicIpButton').Add_Click({try{$Result=Api '/api/public-ip' -Timeout 12;Log ("Public VPN exit: $($Result.public_ip)")}catch{Log $_.Exception.Message}});(Control 'DnsButton').Add_Click({try{$Result=Api '/api/dns/retest' 'POST' @{} 60;Log ("DNS winner: $($Result.winner.address) $($Result.winner.latency_ms)ms")}catch{Log $_.Exception.Message};RefreshProduct});(Control 'EmergencyButton').Add_Click({try{[void](Api '/api/emergency-stop' 'POST' @{} 15);Log 'Emergency stop completed'}catch{Log $_.Exception.Message};RefreshProduct});(Control 'PairNodeButton').Add_Click({try{ShowPairNodeDialog}catch{Log ("Pairing failed: $($_.Exception.Message)")}});(Control 'ImportNodeButton').Add_Click({try{$Picker=New-Object Microsoft.Win32.OpenFileDialog;$Picker.Title='Import Router VPN or external node';$Picker.Filter='Router VPN / external JSON (*.json)|*.json|All files (*.*)|*.*';if($Picker.ShowDialog($Window)){$Bytes=[IO.File]::ReadAllBytes($Picker.FileName);if($Bytes.Length-gt(32MB)){throw 'Node JSON is larger than 32 MiB.'};$Imported=ImportAnyNode $Bytes;Log ("Imported $($Imported.kind) node: $($Imported.result.profile.name)");RefreshProduct}}catch{Log ("Import failed: $($_.Exception.Message)")}});(Control 'ExternalDirectButton').Add_Click({try{ConnectExternal $false}catch{Log ("External direct failed: $($_.Exception.Message)")};RefreshProduct});(Control 'ExternalViaEntryButton').Add_Click({try{ConnectExternal $true}catch{Log ("External via entry failed: $($_.Exception.Message)")};RefreshProduct});(Control 'DeleteNodeButton').Add_Click({try{$Profile=SelectedNode;$Answer=[System.Windows.MessageBox]::Show("Remove linked node '$($Profile.name)' from this app?",'Router VPN',[System.Windows.MessageBoxButton]::YesNo,[System.Windows.MessageBoxImage]::Warning);if($Answer-eq[System.Windows.MessageBoxResult]::Yes){[void](Api '/api/profile/delete' 'POST' @{id=[string]$Profile.id} 10);Log ("Removed node $($Profile.name)");RefreshProduct}}catch{Log ("Remove failed: $($_.Exception.Message)")}});(Control 'SelectNodeButton').Add_Click({try{$Profile=SelectedNode;[void](Api '/api/profile/select' 'POST' @{id=[string]$Profile.id} 10)}catch{Log $_.Exception.Message};RefreshProduct});(Control 'LatencyButton').Add_Click({try{$Profile=SelectedNode;$Result=Api '/api/profile/latency' 'POST' @{id=[string]$Profile.id;samples=50} 180;Log ("Latency median=$($Result.median_ms)ms p90=$($Result.p90_ms)ms")}catch{Log $_.Exception.Message};RefreshProduct});$RouterCombo.Add_SelectionChanged({if($RouterCombo.SelectedValue){try{[void](Api '/api/profile/select' 'POST' @{id=[string]$RouterCombo.SelectedValue} 10)}catch{};RefreshProduct}});(Control 'TutorialButton').Add_Click({[System.Windows.MessageBox]::Show('Install once. In Nodes / Map, pair with a 6-digit one-time code or import Router VPN/external schema-v3 JSON. Order nodes by current/recent, last used, lowest measured latency or name. Automatic lowest-latency choice requires real 50-sample measurements on at least two usable nodes. Highlight an external exit for direct connect, or choose a different entry in Advanced and use External via Advanced entry. Exact public-exit proof is mandatory; unsupported protocol/hop combinations stay rejected.','Router VPN native onboarding')|Out-Null})
